    PRINTFREQS
};
enum VERBOSITY { QUIET, NORMAL, VERBOSE, STATS };
enum DEBUGCOMMAND { NONE, PRINTGRAPH, PRINTGMLGRAPH, PRINTGMLVERTEX };

