        break;
    }

    case CRACK: {
        // Don't print a banner in accessible mode
        if (!Args.Accessible.getValue()) {
            printVersion();
        }
        PasswordCracker pcr;
        pcr.crack();
        break;
    }

    case SEED_CRACK: {
        // Don't print a banner in accessible mode
        if (!Args.Accessible.getValue()) {
            printVersion();
        }
        SeedCracker scr;
