#include <cstdarg>
#include <cstdio>
#include <iostream>
#include <string>

#include "Terminal.h"
#include "colors.h"
#include "common.h"
#include "msg.h"

//
// class MessageBase
//
MessageBase::MessageBase() {
    setMessage(std::string(_("__no_message_defined__")));
    setNewline(true);
}

MessageBase::MessageBase(std::string msg) {
    setMessage(msg);
    setNewline(true);
}

MessageBase::MessageBase(const char *msgfmt, ...) {
    va_list ap;
    va_start(ap, msgfmt);
    setMessage(msgfmt, ap);
    va_end(ap);
    setNewline(true);
}

void MessageBase::setMessage(const char *msgfmt, ...) {
    va_list ap;
    va_start(ap, msgfmt);
    setMessage(vcompose(msgfmt, ap));
    va_end(ap);
}

std::string MessageBase::compose(const char *msgfmt, ...) const {
    va_list ap;
    va_start(ap, msgfmt);
    std::string retval = vcompose(msgfmt, ap);
    va_end(ap);
    return retval;
}

std::string MessageBase::vcompose(const char *msgfmt, va_list ap) {
    char *str = new char[MsgMaxSize];
    vsnprintf(str, MsgMaxSize, msgfmt, ap);
    std::string retval(str);
    delete[] str;
    return retval;
}

//
// class Message
//
Message::Message(const char *msgfmt, ...) : MessageBase() {
    va_list ap;
    va_start(ap, msgfmt);
    setMessage(vcompose(msgfmt, ap));
    va_end(ap);
}

void Message::printMessage() const {
    if (Args.Verbosity.getValue() == NORMAL || Args.Verbosity.getValue() == VERBOSE) {
        std::cerr << getMessage() << getNewline();
    }
}

void Message::print(const char *msgfmt, ...) {
    if (Args.Verbosity.getValue() == NORMAL || Args.Verbosity.getValue() == VERBOSE) {
        va_list ap;
        va_start(ap, msgfmt);
        // print a prefix unless we are in accesible mode
        if (!Args.Accessible.getValue()) {
            std::cerr << "[" << CBLU("i") << "] ";
        }
        std::cerr << vcompose(msgfmt, ap);
    }
}

void Message::printRaw(const char *msgfmt, ...) {
    if (Args.Verbosity.getValue() == NORMAL || Args.Verbosity.getValue() == VERBOSE) {
        va_list ap;
        va_start(ap, msgfmt);
        std::cerr << vcompose(msgfmt, ap);
    }
}

//
// class VerboseMessage
//
VerboseMessage::VerboseMessage(const char *msgfmt, ...) : MessageBase() {
    va_list ap;
    va_start(ap, msgfmt);
    setMessage(vcompose(msgfmt, ap));
    va_end(ap);
    setNewline(true);
}

void VerboseMessage::printMessage() const {
    if (Args.Verbosity.getValue() == VERBOSE) {
        std::cerr << getMessage() << getNewline();
    }
}

void VerboseMessage::print(const char *msgfmt, ...) {
    if (Args.Verbosity.getValue() == VERBOSE) {
        va_list ap;
        va_start(ap, msgfmt);
        // print a prefix unless we are in accesible mode
        if (!Args.Accessible.getValue()) {
            std::cerr << "[" << CYEL("v") << "] ";
        }
        std::cerr << vcompose(msgfmt, ap);
    }
}
void VerboseMessage::printRaw(const char *msgfmt, ...) {
    if (Args.Verbosity.getValue() == VERBOSE) {
        va_list ap;
        va_start(ap, msgfmt);
        std::cerr << vcompose(msgfmt, ap);
    }
}

//
// class Warning
//
Warning::Warning(const char *msgfmt, ...) : MessageBase() {
    va_list ap;
    va_start(ap, msgfmt);
    setMessage(vcompose(msgfmt, ap));
    va_end(ap);
}

void Warning::printMessage() const {
    if (Args.Verbosity.getValue() != QUIET) {
        // print a prefix unless we are in accesible mode
        if (!Args.Accessible.getValue()) {
            std::cerr << "[" << CRED("w") << "] ";
        }
        std::cerr << "warning: " << getMessage() << getNewline();
    }
}

void Warning::print(const char *msgfmt, ...) {
    if (Args.Verbosity.getValue() != QUIET) {
        va_list ap;
        va_start(ap, msgfmt);
        // print a prefix unless we are in accesible mode
        if (!Args.Accessible.getValue()) {
            std::cerr << "[" << CRED("w") << "] ";
        }
        std::cerr << "warning: " << vcompose(msgfmt, ap);
    }
}

//
// class CriticalWarning
//
CriticalWarning::CriticalWarning(const char *msgfmt, ...) : MessageBase() {
    va_list ap;
    va_start(ap, msgfmt);
    setMessage(vcompose(msgfmt, ap));
    va_end(ap);
}

void CriticalWarning::printMessage() const {
    // print a prefix unless we are in accesible mode
    if (!Args.Accessible.getValue()) {
        std::cerr << "[" << CRED("w") << "] ";
    }
    std::cerr << "warning: " << getMessage() << getNewline();
}

void CriticalWarning::print(const char *msgfmt, ...) {
    va_list ap;
    va_start(ap, msgfmt);
    // print a prefix unless we are in accesible mode
    if (!Args.Accessible.getValue()) {
        std::cerr << "[" << CRED("w") << "] ";
    }
    std::cerr << "warning: " << vcompose(msgfmt, ap);
}

//
// class Question
//
Question::Question(void) : MessageBase() {
    yeschar = std::string(_("y"));
    nochar = std::string(_("n"));
}

Question::Question(std::string msg) : MessageBase(msg) {
    yeschar = std::string(_("y"));
    nochar = std::string(_("n"));
}

Question::Question(const char *msgfmt, ...) : MessageBase() {
    yeschar = std::string(_("y"));
    nochar = std::string(_("n"));

    va_list ap;
    va_start(ap, msgfmt);
    setMessage(vcompose(msgfmt, ap));
    va_end(ap);
}

void Question::printMessage() const {
#ifndef HAVE_TERMIOS_H
    Warning w(_("unknown terminal. you might need to press <Enter> after answering."));
    w.printMessage();
#endif
    std::cerr << getMessage() << " (" << yeschar << "/" << nochar << ") ";
}

bool Question::getAnswer() {
    Terminal term;
    term.SingleKeyOn();
    char input[2];
    input[0] = std::cin.get();
    input[1] = '\0';
    bool retval = (std::string(input) == yeschar);
    term.reset();
    std::cerr << std::endl;

    return retval;
}

//
// debugging output
//
#ifdef DEBUG
void printDebug(unsigned short level, const char *msgfmt, ...) {
    if (RUNDEBUGLEVEL(level)) {
        va_list ap;
        va_start(ap, msgfmt);
        vfprintf(stderr, msgfmt, ap);
        va_end(ap);
        fprintf(stderr, "\n");
    }
}
#endif

