    fcntl(errFd, F_SETFD, FD_CLOEXEC);

    std::vector<std::string> command = commandFor(file);
    std::vector<char *> argv;
    for (std::string &argument : command) {
        argv.push_back(const_cast<char *>(argument.c_str()));
